'use strict';
(function(){
const D=EvervaleMapData,copy=x=>JSON.parse(JSON.stringify(x)),fallback=$('gameMapCanvas').querySelector('svg')?.outerHTML||'',actionNames={work:'ทำงาน',train:'ฝึกดาบ',study:'เรียนเวท',explore:'สำรวจ',rest:'พักฟื้น'};
let draft=null,editorBase=null,editingMapId=null,editingPlaceId=null,dirty=false,editorReturn='menuScreen',uploadEpoch=0,imageBusy=false,suppressClick=false;
function config(){return DB.overrides?.[D.KEY]||D.defaults();}
function map(){return draft?.maps.find(x=>x.id===editingMapId);}
function place(){return map()?.locations.find(x=>x.id===editingPlaceId);}
function message(t){$('mapEditorStatus').textContent=t;}
function markDirty(){dirty=true;message('มีการแก้ไขที่ยังไม่บันทึก');}
function safeId(prefix){return prefix+'-'+(crypto.randomUUID?crypto.randomUUID():Math.random().toString(36).slice(2));}
function mapImage(stage,m){stage.replaceChildren();stage.style.aspectRatio=m.width+' / '+m.height;if(m.image){const img=document.createElement('img');img.className='map-background';img.src=m.image;img.alt='แผนที่ '+m.name;img.draggable=false;img.onerror=()=>{if(!stage.querySelector('.map-image-error')){const note=document.createElement('p');note.className='map-image-error';note.textContent='โหลดภาพแผนที่ไม่สำเร็จ • ยังเลือกสถานที่ได้';stage.prepend(note);}};stage.append(img);}else if(fallback)stage.insertAdjacentHTML('afterbegin',fallback);}
function pinElement(p,editor=false){const b=document.createElement('button');b.type='button';b.className=editor?'map-pin editor-pin':'place map-pin';b.style.left=p.x+'%';b.style.top=p.y+'%';b.dataset.locationId=p.id;b.title=p.name;b.setAttribute('aria-label',p.name+(p.targetMapId?' • เข้าแผนที่ย่อย':''));if(!editor&&p.activities[0])b.dataset.place=p.activities[0];if(p.iconImage){const img=document.createElement('img');img.src=p.iconImage;img.alt='';img.draggable=false;b.append(img);}else{const icon=document.createElement('i');icon.textContent=p.icon;icon.setAttribute('aria-hidden','true');b.append(icon);}const label=document.createElement('span');label.textContent=p.name;b.append(label);if(!p.enabled)b.classList.add('pin-disabled');return b;}
function options(){const select=$('mapSelect');select.replaceChildren();for(const m of draft.maps)select.add(new Option(m.name+(m.id===draft.rootId?' • แผนที่หลัก':''),m.id));select.value=editingMapId;$('mapMakeRoot').disabled=map().id===draft.rootId;$('mapDelete').disabled=draft.maps.length===1||map().id===draft.rootId;}
function listPlaces(){const list=$('mapPlaceList');list.replaceChildren();for(const p of map().locations){const b=document.createElement('button');b.type='button';b.className='map-place-row'+(p.id===editingPlaceId?' active':'');b.textContent=p.icon+' '+p.name+(p.enabled?'':' • ซ่อน');b.onclick=()=>selectPlace(p.id);list.append(b);}if(!map().locations.length)list.textContent='ยังไม่มีสถานที่ • กดเพิ่มสถานที่เพื่อเริ่ม';}
function selectPlace(id){editingPlaceId=id;renderPlaceFields();renderEditorStage();listPlaces();}
function renderPlaceFields(){const p=place();$('placeEditPanel').hidden=!p;if(!p)return;$('placeName').value=p.name;$('placeDescription').value=p.description;const icons=$('placeIcon');if(![...icons.options].some(x=>x.value===p.icon))icons.add(new Option(p.icon,p.icon));icons.value=p.icon;$('placeX').value=Math.round(p.x*10)/10;$('placeY').value=Math.round(p.y*10)/10;$('placeEnabled').checked=p.enabled;const target=$('placeTarget');target.replaceChildren(new Option('เปิดสถานที่นี้และทำกิจกรรม',''));for(const other of draft.maps.filter(x=>x.id!==editingMapId))target.add(new Option('เข้าแผนที่: '+other.name,other.id));target.value=p.targetMapId||'';$('placeActivities').hidden=!!p.targetMapId;for(const box of $('placeActivities').querySelectorAll('input'))box.checked=p.activities.includes(box.value);}
function setPosition(p,x,y){p.x=Math.round(Math.max(0,Math.min(100,x))*10)/10;p.y=Math.round(Math.max(0,Math.min(100,y))*10)/10;$('placeX').value=p.x;$('placeY').value=p.y;markDirty();}
function renderEditorStage(){const stage=$('mapEditorCanvas'),m=map();mapImage(stage,m);for(const p of m.locations){const b=pinElement(p,true);b.classList.toggle('selected',p.id===editingPlaceId);let drag=null,moved=false;b.onpointerdown=e=>{if(e.button!==0&&e.pointerType!=='touch')return;e.stopPropagation();drag={x:e.clientX,y:e.clientY,id:e.pointerId};moved=false;b.setPointerCapture(e.pointerId);};b.onpointermove=e=>{if(!drag)return;if(Math.hypot(e.clientX-drag.x,e.clientY-drag.y)<4&&!moved)return;moved=true;const pos=D.position(e.clientX,e.clientY,stage.getBoundingClientRect());p.x=Math.round(pos.x*10)/10;p.y=Math.round(pos.y*10)/10;b.style.left=p.x+'%';b.style.top=p.y+'%';if(p.id===editingPlaceId){$('placeX').value=p.x;$('placeY').value=p.y;}};b.onpointerup=e=>{if(!drag)return;try{b.releasePointerCapture(e.pointerId);}catch{}drag=null;if(moved){suppressClick=true;editingPlaceId=p.id;markDirty();renderPlaceFields();listPlaces();b.classList.add('selected');}};b.onpointercancel=()=>{if(moved){markDirty();editingPlaceId=p.id;renderPlaceFields();}drag=null;};b.onclick=e=>{e.stopPropagation();if(moved){moved=false;suppressClick=false;return;}selectPlace(p.id);};stage.append(b);}stage.onclick=e=>{if(e.target.closest('.map-pin'))return;if(suppressClick){suppressClick=false;return;}const p=place();if(!p){message('กดเพิ่มสถานที่ หรือเลือกสถานที่จากรายการก่อนวางจุด');return;}const pos=D.position(e.clientX,e.clientY,stage.getBoundingClientRect());setPosition(p,pos.x,pos.y);renderEditorStage();};}
function renderEditor(){if(!map()){editingMapId=draft.rootId;editingPlaceId=null;}options();$('mapName').value=map().name;$('mapImageUrl').value=map().image.startsWith('http')?map().image:'';$('mapImageInfo').textContent=map().image?Math.round(map().width)+' × '+Math.round(map().height)+' • ตำแหน่งไอคอนคิดเป็นเปอร์เซ็นต์ของภาพ':'ยังใช้ภาพแผนที่ตัวอย่าง • อัปโหลดภาพของคุณได้';renderEditorStage();listPlaces();renderPlaceFields();}
function openEditor(){uploadEpoch++;imageBusy=false;$('mapSave').disabled=false;draft=copy(config());editorBase=copy(config());if(!draft.maps.some(m=>m.id===editingMapId))editingMapId=draft.rootId;editingPlaceId=null;dirty=false;message('อัปโหลดภาพ แล้วเพิ่มหรือเลือกไอคอนสถานที่เพื่อกำหนดทางเข้า');renderEditor();$('mapCloudStatus').textContent=$('contentCloudStatus').textContent;}
function canLeave(){if((dirty||imageBusy)&&!confirm('แผนที่ยังไม่ได้บันทึก ต้องการออกโดยละทิ้งการแก้ไขหรือไม่?'))return false;dirty=false;uploadEpoch++;imageBusy=false;return true;}
function openFrom(where){editorReturn=where;show('mapEditorScreen');}
$('mapCloudRetry').onclick=()=>$('contentRetry').click();$('mapCloudManage').onclick=()=>{returnScreen='menuScreen';show('databaseScreen');};
$('mapEditorMenu').onclick=()=>openFrom('menuScreen');$('settingsMap').onclick=()=>openFrom('settingsScreen');$('gameMapEdit').onclick=()=>openFrom('gameScreen');$('mapEditorBack').onclick=()=>show(editorReturn);
$('mapSelect').onchange=()=>{uploadEpoch++;imageBusy=false;$('mapSave').disabled=false;editingMapId=$('mapSelect').value;editingPlaceId=null;renderEditor();};
$('mapName').oninput=()=>{map().name=$('mapName').value;markDirty();options();};
$('mapAdd').onclick=()=>{if(draft.maps.length>=20){message('รองรับไม่เกิน 20 แผนที่');return;}const m={id:safeId('map'),name:'แผนที่ใหม่ '+(draft.maps.length+1),image:'',width:800,height:440,locations:[]};draft.maps.push(m);editingMapId=m.id;editingPlaceId=null;markDirty();renderEditor();$('mapName').focus();};
$('mapMakeRoot').onclick=()=>{draft.rootId=editingMapId;markDirty();options();};
$('mapDelete').onclick=()=>{const m=map();if(m.id===draft.rootId||draft.maps.length===1)return;if(!confirm('ลบแผนที่ '+m.name+' และสถานที่ในแผ่นนี้? จุดที่เชื่อมมาจะเปลี่ยนเป็นสถานที่ทั่วไป'))return;draft.maps=draft.maps.filter(x=>x.id!==m.id);for(const other of draft.maps)for(const p of other.locations)if(p.targetMapId===m.id)p.targetMapId=null;editingMapId=draft.rootId;editingPlaceId=null;uploadEpoch++;markDirty();renderEditor();};
$('mapAddPlace').onclick=()=>{if(map().locations.length>=80){message('รองรับไม่เกิน 80 สถานที่ต่อแผนที่');return;}const p={id:safeId('place'),name:'สถานที่ใหม่',icon:'📍',iconImage:'',x:50,y:50,description:'',targetMapId:null,activities:[],enabled:true};map().locations.push(p);markDirty();selectPlace(p.id);$('placeName').focus();};
$('mapDeletePlace').onclick=()=>{const p=place();if(!p||!confirm('ลบสถานที่ '+p.name+'?'))return;map().locations=map().locations.filter(x=>x.id!==p.id);editingPlaceId=null;markDirty();renderEditor();};
$('placeName').oninput=()=>{if(!place())return;place().name=$('placeName').value;markDirty();listPlaces();renderEditorStage();};$('placeDescription').oninput=()=>{if(place()){place().description=$('placeDescription').value;markDirty();}};
$('placeIcon').onchange=()=>{if(place()){place().icon=$('placeIcon').value;place().iconImage='';markDirty();renderEditorStage();listPlaces();}};
for(const [id,key] of [['placeX','x'],['placeY','y']])$(id).oninput=()=>{const value=Number($(id).value);if(place()&&Number.isFinite(value)){setPosition(place(),key==='x'?value:place().x,key==='y'?value:place().y);renderEditorStage();}};
$('placeEnabled').onchange=()=>{if(place()){place().enabled=$('placeEnabled').checked;markDirty();renderEditorStage();listPlaces();}};
$('placeTarget').onchange=()=>{if(place()){place().targetMapId=$('placeTarget').value||null;$('placeActivities').hidden=!!place().targetMapId;markDirty();}};
$('placeActivities').onchange=()=>{if(place()){place().activities=Array.from($('placeActivities').querySelectorAll('input:checked')).map(x=>x.value);markDirty();}};
function decodeImage(src){return new Promise((resolve,reject)=>{const img=new Image(),timer=setTimeout(()=>{img.src='';reject(Error('โหลดภาพไม่สำเร็จ กรุณาตรวจลิงก์หรือใช้ไฟล์ภาพ'));},15000);img.onload=()=>{clearTimeout(timer);resolve(img);};img.onerror=()=>{clearTimeout(timer);reject(Error('อ่านภาพไม่ได้ กรุณาใช้ PNG JPEG WebP หรือ GIF'));};img.src=src;});}
async function uploadedImage(file,icon=false){if(!file||!/^image\/(png|jpeg|webp|gif)$/.test(file.type))throw Error('รองรับ PNG JPEG WebP GIF');if(file.size>10*1024*1024)throw Error('ไฟล์ภาพต้นฉบับต้องไม่เกิน 10 MB');const url=URL.createObjectURL(file);try{const img=await decodeImage(url),limit=icon?96:1800,scale=Math.min(1,limit/Math.max(img.naturalWidth,img.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.naturalWidth*scale));canvas.height=Math.max(1,Math.round(img.naturalHeight*scale));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);let data=canvas.toDataURL('image/webp',.8);for(const q of [.65,.5,.35])if(data.length>(icon?70000:850000))data=canvas.toDataURL('image/webp',q);if(data.length>(icon?100000:1100000))throw Error('ภาพยังใหญ่เกินไป กรุณาลดรายละเอียดหรือขนาดไฟล์');return {image:data,width:canvas.width,height:canvas.height};}finally{URL.revokeObjectURL(url);}}
async function changeImage(fn,icon=false){const token=++uploadEpoch,mapId=editingMapId,placeId=editingPlaceId;imageBusy=true;$('mapSave').disabled=true;message('กำลังเตรียมภาพ…');try{const data=await fn();if(token!==uploadEpoch||!draft||mapId!==editingMapId||icon&&placeId!==editingPlaceId)return;if(icon){place().iconImage=data.image;}else{Object.assign(map(),data);}$('mapImageFile').value=$('placeIconFile').value='';markDirty();renderEditor();message('ภาพพร้อมแล้ว • กดบันทึกแผนที่และซิงก์เพื่อใช้ในเกม');}catch(e){if(token===uploadEpoch)message(e.message);}finally{if(token===uploadEpoch){imageBusy=false;$('mapSave').disabled=false;}}}
$('mapImageFile').onchange=e=>{const file=e.target.files[0];if(file)changeImage(()=>uploadedImage(file));};
$('placeIconFile').onchange=e=>{const file=e.target.files[0];if(file&&place())changeImage(()=>uploadedImage(file,true),true);};
$('mapLoadUrl').onclick=()=>changeImage(async()=>{const image=$('mapImageUrl').value.trim();D.image(image);if(!image)throw Error('ใส่ลิงก์ภาพก่อน');const img=await decodeImage(image),scale=Math.min(1,10000/Math.max(img.naturalWidth,img.naturalHeight));return {image,width:img.naturalWidth*scale,height:img.naturalHeight*scale};});
$('mapClearImage').onclick=()=>{uploadEpoch++;imageBusy=false;$('mapSave').disabled=false;map().image='';map().width=800;map().height=440;markDirty();renderEditor();};$('placeClearIcon').onclick=()=>{if(place()){uploadEpoch++;imageBusy=false;$('mapSave').disabled=false;place().iconImage='';markDirty();renderEditorStage();}};
$('mapSave').onclick=()=>{if(imageBusy)return;try{const data=D.validate(draft);if(!EvervaleLibraryMerge.equal(config(),editorBase)&&!confirm('แผนที่ที่บันทึกไว้เปลี่ยนจากอีกเครื่องระหว่างแก้ไข ต้องการใช้ฉบับที่กำลังแก้แทนหรือไม่?'))return;const previous=dirty;dirty=false;try{persistContentEdits({...DB.overrides,[D.KEY]:data});}catch(e){dirty=previous;throw e;}draft=copy(data);editorBase=copy(data);message('บันทึกแผนที่ในเครื่องแล้ว • ดูสถานะ Supabase ด้านล่าง');renderEditor();}catch(e){message('บันทึกไม่ได้: '+e.message);}};
$('mapReload').onclick=()=>{if((dirty||imageBusy)&&!confirm('ละทิ้งการแก้ไข แล้วโหลดแผนที่ฉบับที่บันทึกไว้?'))return;openEditor();};
function gameView(c){const view=s.mapView&&typeof s.mapView==='object'?s.mapView:{};const valid=c.maps.some(m=>m.id===view.mapId);return {mapId:valid?view.mapId:c.rootId,placeId:valid&&typeof view.placeId==='string'?view.placeId:null,history:Array.isArray(view.history)?view.history.filter(id=>typeof id==='string'&&c.maps.some(m=>m.id===id)).slice(-20):[]};}
function navigate(view){s.mapView=view;save();render();}
function renderGame(){if(!s.character)return;const c=config(),view=gameView(c),m=c.maps.find(x=>x.id===view.mapId)||c.maps[0],stage=$('gameMapCanvas');stage.classList.add('map-stage');mapImage(stage,m);const nav=$('gameMapNav');nav.replaceChildren();const root=document.createElement('button');root.type='button';root.textContent='⌂ '+c.maps.find(x=>x.id===c.rootId).name;root.onclick=()=>navigate({mapId:c.rootId,placeId:null,history:[]});nav.append(root);if(view.history.length){const back=document.createElement('button');back.type='button';back.textContent='← กลับแผนที่ก่อนหน้า';back.onclick=()=>{const history=[...view.history],id=history.pop();navigate({mapId:id,placeId:null,history});};nav.append(back);}const title=document.createElement('strong');title.textContent=m.name;nav.append(title);for(const p of m.locations.filter(x=>x.enabled)){const b=pinElement(p);b.classList.toggle('selected',p.id===view.placeId);b.onclick=()=>{if(p.targetMapId)navigate({mapId:p.targetMapId,placeId:null,history:[...view.history,m.id].slice(-20)});else{if(p.activities[0])selected=p.activities[0];navigate({...view,placeId:p.id});}};stage.append(b);}const p=m.locations.find(x=>x.id===view.placeId&&x.enabled&&!x.targetMapId),loc=$('location');loc.replaceChildren();if(!p){const h=document.createElement('h2');h.textContent='เลือกสถานที่ใน'+m.name;const desc=document.createElement('p');desc.textContent=m.locations.some(x=>x.enabled)?'กดไอคอนเพื่อเข้าไปในสถานที่ หรือเดินทางสู่แผนที่ย่อย • การเปิดดูสถานที่ไม่ทำให้เวลาเดิน':'แผนที่นี้ยังไม่มีสถานที่ • เพิ่มไอคอนได้จากหน้าแก้ไขแผนที่';loc.append(h,desc);return;}const eyebrow=document.createElement('p');eyebrow.className='eyebrow';eyebrow.textContent='YOU ARE HERE';const h=document.createElement('h2');h.textContent=p.icon+' '+p.name;const desc=document.createElement('p');desc.textContent=p.description||'คุณเข้ามาในสถานที่นี้แล้ว';const buttons=document.createElement('div');buttons.className='location-actions';p.activities.forEach((a,i)=>{const b=document.createElement('button');b.type='button';if(i===0)b.id='manual';b.className='primary';b.dataset.mapAction=a;b.textContent=actionNames[a]+' • '+(a==='explore'?2:R.durations[a]/60)+' ชม.';b.disabled=s.dead||!!s.event;b.onclick=()=>{selected=a;run(1,a);};buttons.append(b);});const back=document.createElement('button');back.type='button';back.textContent='ออกจากสถานที่';back.onclick=()=>navigate({...view,placeId:null});buttons.append(back);const note=document.createElement('p');note.className='muted';note.textContent=p.activities.length?'กิจกรรมใช้กติกาเดิม รวมเงื่อนไขพักและเงินสำรอง • เวลาเดินเมื่อทำกิจกรรมหรือดำเนินแผน':'สถานที่นี้ยังไม่ได้กำหนดกิจกรรม • เพิ่มได้จากหน้าแก้ไขแผนที่';loc.append(eyebrow,h,desc,buttons,note);}
window.EvervaleMaps={openEditor,canLeave,renderGame,reset(){uploadEpoch++;draft=null;editorBase=null;editingMapId=null;editingPlaceId=null;dirty=false;imageBusy=false;},libraryUpdated(){if(screen==='gameScreen')renderGame();if(screen==='mapEditorScreen'&&draft){if(dirty||imageBusy)message('ข้อมูลคลาวด์เปลี่ยนระหว่างแก้ไข • ฉบับที่กำลังแก้ยังอยู่ กดบันทึกหรือโหลดฉบับที่บันทึกไว้');else openEditor();}}};
})();
